INSERT INTO SPC_DialogueLevels WITH RECURSIVE levels(n) AS (SELECT 2 WHERE (SELECT COUNT(*) FROM Eras)>=2 UNION ALL SELECT n+1 FROM levels WHERE n<(SELECT COUNT(*) FROM Eras)) SELECT n FROM levels;
INSERT INTO Types(Type,Kind) SELECT 'BUILDING_SPC_B059_D'||D,'KIND_BUILDING' FROM SPC_DialogueLevels;
INSERT INTO Buildings(BuildingType,Name,Cost,PrereqDistrict,InternalOnly,CitizenSlots,Housing) SELECT 'BUILDING_SPC_B059_D'||D,'Dialogue Across Eras',1,'DISTRICT_CITY_CENTER',1,0,0 FROM SPC_DialogueLevels;
